@Composable
fun LocalLogin(store: ConnectedStore) {
    var selectedPhone by rememberSaveable { mutableStateOf("13800000003") }
    var connectionDialog by remember { mutableStateOf(false) }
    var agreed by rememberSaveable { mutableStateOf(false) }
    val loading by store.loading.collectAsState()
    val sessionAvailable by store.sessionAvailable.collectAsState()
    val connectionError by store.error.collectAsState()
    val driverAccounts = listOf(
        "13800000001" to "体验司机01 (13800000001)",
        "13800000002" to "体验司机02 (13800000002)",
        "13800000003" to "体验司机03 (13800000003)",
    )

    Column(
        Modifier.fillMaxSize().imePadding().verticalScroll(rememberScrollState()).padding(20.dp)
    ) {
        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
            CoreTextButton(
                onClick = { connectionDialog = true }
            ) {
                Text("连接状态", fontSize = 16.sp)
            }
        }
        androidx.compose.foundation.Image(
            painter = androidx.compose.ui.res.painterResource(R.drawable.yijiexing_welcome_hero),
            contentDescription = "宜捷行出租车与司机品牌插画",
            contentScale = androidx.compose.ui.layout.ContentScale.Crop,
            alignment = Alignment.BottomCenter,
            modifier = Modifier.fillMaxWidth().height(220.dp).clip(RoundedCornerShape(22.dp)),
        )
        Spacer(Modifier.height(18.dp))
        Text("宜捷行 · 司机", fontSize = 28.sp, fontWeight = FontWeight.Bold, color = Green)
        Text("欢迎回来，师傅", color = Ink, fontSize = 20.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.padding(top = 4.dp))
        Text("免访问码体验 · 选择体验账号一键进入", color = Muted, fontSize = 13.sp, modifier = Modifier.padding(top = 8.dp, bottom = 12.dp))

        if (!sessionAvailable && connectionError != null) {
            Spacer(Modifier.height(12.dp))
            SheetCard {
                Text(
                    "连接未完成",
                    fontWeight = FontWeight.SemiBold,
                    color = MaterialTheme.colorScheme.error,
                )
                Text(
                    connectionError!!,
                    fontSize = 16.sp,
                    color = Muted,
                    modifier = Modifier.padding(top = 8.dp),
                )
                CoreTextButton(
                    onClick = { connectionDialog = true }
                ) {
                    Text("查看连接状态")
                }
            }
        }
        if (sessionAvailable) {
            Spacer(Modifier.height(14.dp))
            SheetCard {
                Text("服务连接提示", fontWeight = FontWeight.SemiBold, color = Ink)
                Text(
                    connectionError ?: "若遇网络波动或服务休眠，可点下方按钮重试连接。",
                    fontSize = 16.sp,
                    color = Muted,
                    modifier = Modifier.padding(top = 8.dp),
                )
                Spacer(Modifier.height(10.dp))
                PrimaryButton("重试连接", onClick = { store.refresh() })
            }
        }

        Spacer(Modifier.height(20.dp))
        Text("选择体验司机账号", fontSize = 16.sp, fontWeight = FontWeight.SemiBold, color = Ink)
        Spacer(Modifier.height(8.dp))

        driverAccounts.forEach { (phone, label) ->
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(min = 48.dp)
                    .selectable(
                        selected = (phone == selectedPhone),
                        role = Role.RadioButton,
                        onClick = { selectedPhone = phone }
                    )
                    .padding(vertical = 4.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                RadioButton(
                    selected = (phone == selectedPhone),
                    onClick = null
                )
                Text(
                    text = label,
                    fontSize = 16.sp,
                    color = Ink,
                    modifier = Modifier.padding(start = 12.dp)
                )
            }
        }

        Spacer(Modifier.height(12.dp))
        Row(
            Modifier.fillMaxWidth()
                .heightIn(min = 48.dp)
                .toggleable(
                    value = agreed,
                    role = Role.Checkbox,
                    onValueChange = { agreed = it },
                )
                .padding(vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Checkbox(agreed, onCheckedChange = null)
            Text(
                "我已了解体验说明，账号仅用于本次体验",
                fontSize = 16.sp,
                color = Ink,
                modifier = Modifier.weight(1f).padding(start = 10.dp),
            )
        }

        Spacer(Modifier.height(8.dp))
        PrimaryButton(
            if (loading) "正在进入…" else "进入体验",
            enabled = !loading && agreed,
            onClick = {
                store.loginExperience(selectedPhone)
            },
        )

        Spacer(Modifier.height(20.dp))
        SheetCard {
            Text("体验说明", fontSize = 18.sp, fontWeight = FontWeight.Bold)
            Text(
                "体验账号共用演示数据；支付、退款为模拟，不会真实扣款。请使用演示资料。",
                color = Muted,
                fontSize = 16.sp,
                lineHeight = 24.sp,
                modifier = Modifier.padding(top = 8.dp),
            )
            Text(
                "本应用用于独立演示验证。已免除访问码，选择账号即可体验司机抢单、计价与行程管理；未对接真实短信、实名认证与银行结算。",
                color = Muted,
                fontSize = 14.sp,
                lineHeight = 20.sp,
                modifier = Modifier.padding(top = 6.dp),
            )
        }
        Text(
            "本版不连接现有测试或生产环境",
            fontSize = 14.sp,
            color = Muted,
            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
        )
    }

    if (connectionDialog) {
        CloudConnectionDialog(
            store = store,
            onDismiss = { connectionDialog = false },
        )
    }
}

driver.CloudConnectionDialog:
@Composable
private fun CloudConnectionDialog(
    store: ConnectedStore,
    reason: String? = null,
    onDismiss: () -> Unit,
) {
    val connectionError by store.error.collectAsState()
    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text("连接状态") },
        text = {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(10.dp),
            ) {
                reason?.let {
                    Text(
                        it,
                        color = Green,
                        fontSize = 16.sp,
                        fontWeight = FontWeight.SemiBold,
                    )
                }
                Text(
                    "体验服务正常运行中。若遇网络波动或服务休眠，请点击下方“重试连接”。",
                    fontSize = 16.sp,
                    color = Ink,
                )
                if (connectionError != null) {
                    Text(
                        connectionError!!,
                        color = MaterialTheme.colorScheme.error,
                        fontSize = 14.sp,
                    )
                }
            }
        },
        confirmButton = {
            CoreTextButton(
                onClick = {
                    store.refresh()
                }
            ) {
                Text("重试连接")
            }
        },
        dismissButton = {
            CoreTextButton(onClick = onDismiss) {
                Text("关闭")
            }
        },
    )
}

passenger.LoginScreen:
@Composable
fun LoginScreen(store: PassengerStore, configured: Boolean, settings: () -> Unit) {
  var mobile by rememberSaveable { mutableStateOf("13800000102") }
  var agreed by rememberSaveable { mutableStateOf(false) }
  val busy by store.busy.collectAsState()
  val error by store.error.collectAsState()
  val passengerAccounts = listOf(
    "13800000101" to "体验乘客01 (13800000101)",
    "13800000102" to "体验乘客02 (13800000102)",
    "13800000103" to "体验乘客03 (13800000103)",
  )

  Column(
    Modifier
      .fillMaxSize()
      .background(Paper)
      .verticalScroll(rememberScrollState())
      .imePadding()
  ) {
    Image(
      painter = painterResource(id = R.drawable.yijiexing_welcome_hero),
      contentDescription = "宜捷行品牌插画",
      modifier = Modifier
        .fillMaxWidth()
        .height(240.dp),
      contentScale = ContentScale.Crop,
      alignment = Alignment.BottomCenter,
    )
    Column(
      Modifier
        .fillMaxWidth()
        .padding(horizontal = 16.dp, vertical = 12.dp),
      verticalArrangement = Arrangement.spacedBy(14.dp),
    ) {
      Row(
        Modifier.fillMaxWidth().padding(vertical = 4.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically,
      ) {
        Column(
          modifier = Modifier.weight(1f),
          verticalArrangement = Arrangement.spacedBy(4.dp),
        ) {
          Text(
            "宜捷出行，欢迎您！",
            fontSize = 22.sp,
            fontWeight = FontWeight.Bold,
            color = Ink,
          )
          Note("选择目的地，查看司机报价，与司机端共享同一订单")
        }
        TextButton(
          onClick = settings,
          modifier = Modifier.heightIn(min = 48.dp),
        ) {
          Text("连接状态", color = Teal, fontSize = 14.sp)
        }
      }
      Panel("选择体验乘客账号") {
        passengerAccounts.forEach { (phone, label) ->
          Row(
            modifier = Modifier
              .fillMaxWidth()
              .heightIn(min = 48.dp)
              .selectable(
                selected = (mobile == phone),
                role = Role.RadioButton,
                onClick = { mobile = phone },
              )
              .padding(vertical = 4.dp),
            verticalAlignment = Alignment.CenterVertically,
          ) {
            RadioButton(
              selected = (mobile == phone),
              onClick = null,
              colors = RadioButtonDefaults.colors(selectedColor = Teal),
            )
            Text(
              text = label,
              fontSize = 16.sp,
              color = Ink,
              modifier = Modifier.padding(start = 10.dp),
            )
          }
        }
        Row(
          verticalAlignment = Alignment.CenterVertically,
          modifier = Modifier
            .fillMaxWidth()
            .heightIn(min = 48.dp)
            .toggleable(value = agreed, role = Role.Checkbox, onValueChange = { agreed = it }),
        ) {
          Checkbox(
            checked = agreed,
            onCheckedChange = null,
            colors = CheckboxDefaults.colors(checkedColor = Teal),
          )
          Spacer(Modifier.width(8.dp))
          Text("我已阅读并同意下方体验说明", fontSize = 14.sp, color = Ink)
        }
        error?.let {
          Text(it, color = MaterialTheme.colorScheme.error, fontSize = 14.sp)
        }
        ActionButton(if (busy) "正在进入…" else "进入体验", agreed && !busy) {
          store.loginExperience(mobile)
        }
      }
      Panel("体验说明与数据范围") {
        Note(
          "体验账号共用演示数据；支付、退款为模拟，不会真实扣款。请使用演示资料。"
        )
        Spacer(Modifier.height(6.dp))
        Note(
          "本应用用于独立演示环境验证。订单真实保存并同步到司机端；付款、退款和发票均为模拟，不发生真实扣款。请使用合成资料，不填写真实身份信息。未接道路导航、自动定位、短信、电话中继、推送或实时人工客服；退出登录会移除本机体验状态，云端订单记录保留。"
        )
      }
      Spacer(Modifier.height(16.dp))
    }
  }
}

passenger.SettingsDialog:
@Composable
fun SettingsDialog(store: PassengerStore, configured: Boolean, close: () -> Unit) {
  val settingsError by store.error.collectAsState()
  AlertDialog(
    onDismissRequest = close,
    title = { Text("连接状态") },
    text = {
      Column(
        Modifier.verticalScroll(rememberScrollState()),
        verticalArrangement = Arrangement.spacedBy(12.dp),
      ) {
        Note("演示服务正常连接中。本体验环境独立运行，无需配置访问码，下载后即可直接使用。")
        settingsError?.let { Text(it, color = MaterialTheme.colorScheme.error, fontSize = 14.sp) }
        Note("如遇网络切换或服务暂停，可点击“重试连接”恢复通信。")
      }
    },
    confirmButton = {
      TextButton(
        onClick = { store.refresh() },
      ) {
        Text("重试连接", color = Teal)
      }
    },
    dismissButton = { TextButton(onClick = close) { Text("关闭") } },
  )
}
